#!/usr/bin/env python3
import collections,json,sqlite3,sys
from pathlib import Path
base=Path('.git/platform-v2/local/node-map-expansion'); db=sqlite3.connect(sys.argv[1])
ledger=json.loads((Path(sys.argv[2])/'ledger.json').read_bytes()); taxa=json.loads((base/'taxa-v5/state.json').read_bytes()); occurrences=json.loads((base/'occurrences/state.json').read_bytes()); inputs=json.loads((base/'input-v5.json').read_bytes())
data={'occurrenceQueue':{'requested':occurrences['cursor'],'returned':occurrences['cursor']-len(occurrences['unreturned']),'unreturned':len(occurrences['unreturned']),'remaining':len(occurrences['queue'])-occurrences['cursor'],'failed':bool(occurrences.get('lastError'))},'input':inputs['download'],'originalInput':inputs['counts'],'totalConflictedIds':inputs['conflictIds'],'taxa':{'requested':len(taxa['attempted']),'returned':len(taxa['returned']),'unreturned':len(set(taxa['attempted'])-set(taxa['returned'])),'remaining':len(taxa['frontier'])},'ledgerReasons':dict(collections.Counter(x.get('reason','conflict') for x in ledger['entries'])),'identifiedTaxa':db.execute('SELECT count(distinct node_id) FROM map_occurrence').fetchone()[0],'reconstructedOccurrences':db.execute("SELECT count(distinct occurrence_id) FROM map_occurrence_position WHERE status='ready'").fetchone()[0],'referenceIds':db.execute("SELECT count(*) FROM map_occurrence_evidence_detail WHERE reference_id IS NOT NULL AND reference_id<>''").fetchone()[0],'sourceMemberships':db.execute('SELECT count(*) FROM map_occurrence_source_membership').fetchone()[0]}
print(json.dumps(data,ensure_ascii=False,sort_keys=True))
